// Imports the OpenAI library to allow for interaction with the llama.cpp compatible endpoint
import OpenAI from "openai";
import * as readline from "node:readline/promises";
import { stdin as input, stdout as output } from "node:process";


/**
 * Creates an OpenAI Object which allows for easy reference to our http compatible
 *  endpoint throughout the program.
 *
 *  PREREQ:
 *      - process.env: process is an object generated by Node.js which allows you to get access to the runtime
 *          environment that the program is active in. process.env specifically gives you access to all of the
 *          environment variables that are declared.
 *
 *      - ?? operator: the ?? operator otherwise known as the nullish coalescing operator essentially says
 *          if whatever on the left is null or undefined, use what is on the right as the default
 */
const client = new OpenAI({
    baseURL: process.env.MODEL_BASE_URL ?? "http://gemma.lan/v1",
    apiKey: process.env.MODEL_API_KEY ?? "local",
})


// Set a model variable so that it can be referenced and swapped out in the code, it is not set in the constructor
//  as an endpoints model may be changed
const MODEL = process.env.MODEL_ID ?? "gemma-4-12b";

/**
 *  The function which prompts the LLM for a response utilizing the chat completions
 *      api. The create function accepts a ChatCompletionsCreateParamsBase object with
 *      subclasses for streaming functionality. Details about the configuration of the object
 *      can be found at https://developers.openai.com/api/reference/typescript/resources/chat/subresources/completions/methods/create.
 *      The object has a required message and model field with 34 other optional fields.
 *
 *  PREREQ:
 *      - messages: There are multiple different options for the object signature for message. Right now it is
 *          confusing as to when to use what so for simple response testing, use a user role
 *      - model: The model to use on the llm server
 *      - async: Denotes the function to run concurrently in the program. Allows for the use of await in the function
 *      - await: Allows for a function / return value to pause the execution of a conccurent piece of code and hand
 *          back functionality to the main program until it is done executing
 *
 */
async function response(prompt: string) {
    const completions = await client.chat.completions.create({
        messages: [{role: "user", content: prompt}],
        model: MODEL,
    })

    console.log(completions.choices[0].message.content)
}

const rl = readline.createInterface({ input, output });
const prompt = await rl.question("Enter Prompt Here > ");
rl.close();

response(prompt)

